; cart8.asm -- chapter 15: a cartridge of 8 KB
; generated by gen15.py
        INCLUDE "msx.inc"
        OUTPUT "cart8.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; A cartridge of 8 KB, the size of many early MSX games: the same header,
; and the padding stops at $6000.
init:   di
        ld sp, SYS_AREA
        VDP_REG 7, LIGHT_GREEN  ; the border light green: it runs
stop:   jr stop
        ASSERT $ <= $6000, the program is longer than 8 KB
        ds $6000 - $, $FF       ; pad the cartridge to 8 KB
